import { atom, read, update } from 'claude-code'
import type { Register } from 'claude-code'

import type { Block } from '../types'

const last = atom({ plugin: 'secret-guard', key: 'last' } as const, null)

const ENV_FILE = /(^|[\/\s'"=])\.env(\.[\w.-]+)?($|[\s'"])/
const ENV_SAMPLE = /\.env\.(example|sample|template)\b/
const KEY_VAR = /\$\{?[A-Za-z0-9_]*(API_?KEY|SECRET|TOKEN|PASSWORD)[A-Za-z0-9_]*\}?/i
const KEY_LITERAL =
  /\b(sk-[A-Za-z0-9_-]{16,}|sk-ant-[A-Za-z0-9_-]{16,}|AKIA[0-9A-Z]{16}|gh[pousr]_[A-Za-z0-9]{30,}|xox[baprs]-[A-Za-z0-9-]{10,})\b/
const DUMP_ENV = /(^|[;&|]\s*)(printenv|env|export\s+-p|set)\s*($|[;&|])/
const PRINTS = /\b(echo|printf|cat|print|printenv)\b/

const isEnvPath = (p: unknown): p is string =>
  typeof p === 'string' && ENV_FILE.test(p) && !ENV_SAMPLE.test(p)

const inspect = (e: Record<string, any>): { reason: string; target: string } | null => {
  for (const key of ['file_path', 'path', 'pattern', 'notebook_path']) {
    if (isEnvPath(e[key])) return { reason: 'Read of a .env file', target: e[key] }
  }

  const cmd = e.command
  if (typeof cmd === 'string') {
    if (ENV_FILE.test(cmd) && !ENV_SAMPLE.test(cmd)) {
      return { reason: 'Command touching a .env file', target: cmd.slice(0, 60) }
    }
    if (KEY_LITERAL.test(cmd) && PRINTS.test(cmd)) {
      return { reason: 'Printing an API key', target: cmd.slice(0, 60) }
    }
    if (PRINTS.test(cmd) && KEY_VAR.test(cmd)) {
      return { reason: 'Printing an API key variable', target: cmd.slice(0, 60) }
    }
    if (DUMP_ENV.test(cmd)) {
      return { reason: 'Dumping environment variables', target: cmd.slice(0, 60) }
    }
  }

  return null
}

export const register: Register = on => {
  on('tool.call', async ($, e, next) => {
    const hit = inspect(e as Record<string, any>)

    if (hit === null) {
      return next(e)
    }

    const block: Block = { tool: String(e.tool), ...hit }
    await update($, last, () => block)

    return {
      deny: `secret-guard blocked this: ${hit.reason}. Do not read .env files or print secrets.`,
    }
  })

  on('prompt.submit', async ($, e, next) => {
    await update($, last, () => null)

    return next(e)
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const block = await read($, last)

    if (block === null) {
      return next(e)
    }

    const { Box, Text } = $.ui.resolve(e)

    return (
      <Box>
        <Text color="red" bold>
          🛡 secret-guard blocked {block.tool}: {block.reason} ({block.target})
        </Text>
      </Box>
    )
  })
}

